from __future__ import print_function

import json
import os
import re
import struct
import sys
import zlib

SCRIPT_DIR = os.path.dirname(os.path.abspath(__file__))
PROJECT_ROOT = os.path.dirname(SCRIPT_DIR)
ART_DIR = os.path.join(PROJECT_ROOT, "Art")
UPROJECT = os.path.join(PROJECT_ROOT, "SpriteLab.uproject")

NAME_RE = re.compile(r"^[a-z][a-z0-9_]*$")
PNG_SIG = b"\x89PNG\r\n\x1a\n"
ALLOWED_ANGLES = (1, 5, 8)
MIRROR_SRC = {5: 3, 6: 2, 7: 1}  # Angles=5: a5/a6/a7 show a3/a2/a1 flipped
CONTENT_ROOT = "/Game/Lab"
PREVIEW_MAP = "/Game/Lab/Preview"
TAG_PREFIX = "spritelab:"
TAG_TOOL = "spritelab"
TAG_RIG = "spritelab:rig"

# 5x7 digits for the test sheet only (not game art).
_DIGITS = {
    "0": ["01110", "10001", "10001", "10001", "10001", "10001", "01110"],
    "1": ["00100", "01100", "00100", "00100", "00100", "00100", "01110"],
    "2": ["01110", "10001", "00001", "00110", "01000", "10000", "11111"],
    "3": ["11110", "00001", "00001", "01110", "00001", "00001", "11110"],
    "4": ["00010", "00110", "01010", "10010", "11111", "00010", "00010"],
    "5": ["11111", "10000", "11110", "00001", "00001", "10001", "01110"],
    "6": ["01110", "10000", "11110", "10001", "10001", "10001", "01110"],
    "7": ["11111", "00001", "00010", "00100", "01000", "01000", "01000"],
    "8": ["01110", "10001", "10001", "01110", "10001", "10001", "01110"],
    "9": ["01110", "10001", "10001", "01111", "00001", "00001", "01110"],
}


def _log(kind, path, detail=""):
    extra = "  " + detail if detail else ""
    print("{0:5} {1}{2}".format(kind, path, extra))


def _try_unreal():
    try:
        import unreal
        return unreal
    except ImportError:
        return None


def plugin_status():
    """Read SpriteLab.uproject; Paper2D / PythonScriptPlugin must be enabled there."""
    out = {"Paper2D": False, "PythonScriptPlugin": False, "exists": os.path.isfile(UPROJECT)}
    if not out["exists"]:
        return out
    with open(UPROJECT, "r", encoding="utf-8") as f:
        data = json.load(f)
    for plug in data.get("Plugins") or []:
        name = plug.get("Name")
        if name in out and plug.get("Enabled") is True:
            out[name] = True
    return out


# --- minimal PNG (zlib + struct): RGBA / RGB / 8-bit palette, non-interlaced ---

def _paeth(a, b, c):
    p = a + b - c
    pa, pb, pc = abs(p - a), abs(p - b), abs(p - c)
    if pa <= pb and pa <= pc:
        return a
    if pb <= pc:
        return b
    return c


def _unfilter(data, width, height, bpp):
    stride = width * bpp
    out = bytearray(height * stride)
    prev = bytearray(stride)
    i = 0
    for y in range(height):
        ftype = data[i]
        i += 1
        raw = bytearray(data[i:i + stride])
        i += stride
        if ftype == 0:
            pass
        elif ftype == 1:
            for x in range(stride):
                left = raw[x - bpp] if x >= bpp else 0
                raw[x] = (raw[x] + left) & 255
        elif ftype == 2:
            for x in range(stride):
                raw[x] = (raw[x] + prev[x]) & 255
        elif ftype == 3:
            for x in range(stride):
                left = raw[x - bpp] if x >= bpp else 0
                raw[x] = (raw[x] + ((left + prev[x]) // 2)) & 255
        elif ftype == 4:
            for x in range(stride):
                left = raw[x - bpp] if x >= bpp else 0
                up = prev[x]
                ul = prev[x - bpp] if x >= bpp else 0
                raw[x] = (raw[x] + _paeth(left, up, ul)) & 255
        else:
            raise ValueError("unsupported PNG filter {0}".format(ftype))
        out[y * stride:(y + 1) * stride] = raw
        prev = raw
    return out


def read_png(path):
    with open(path, "rb") as f:
        blob = f.read()
    if blob[:8] != PNG_SIG:
        raise ValueError("not a PNG")
    pos = 8
    width = height = bit_depth = color_type = None
    interlace = 0
    palette = None
    trns = None
    idat = []
    while pos + 8 <= len(blob):
        length = struct.unpack(">I", blob[pos:pos + 4])[0]
        tag = blob[pos + 4:pos + 8]
        data = blob[pos + 8:pos + 8 + length]
        pos += 12 + length
        if tag == b"IHDR":
            width, height, bit_depth, color_type, _comp, _filt, interlace = struct.unpack(">IIBBBBB", data)
        elif tag == b"PLTE":
            palette = [(data[i], data[i + 1], data[i + 2]) for i in range(0, len(data), 3)]
        elif tag == b"tRNS":
            trns = data
        elif tag == b"IDAT":
            idat.append(data)
        elif tag == b"IEND":
            break
    if width is None:
        raise ValueError("missing IHDR")
    if interlace != 0:
        raise ValueError("interlaced PNG not supported")
    if bit_depth != 8:
        raise ValueError("bit depth {0} not supported (need 8)".format(bit_depth))
    raw = zlib.decompress(b"".join(idat))
    if color_type == 6:
        bpp = 4
        pixels = _unfilter(raw, width, height, bpp)
        rgba = pixels
    elif color_type == 2:
        bpp = 3
        pixels = _unfilter(raw, width, height, bpp)
        rgba = bytearray(width * height * 4)
        for i in range(width * height):
            rgba[i * 4:i * 4 + 3] = pixels[i * 3:i * 3 + 3]
            rgba[i * 4 + 3] = 255
        if trns and len(trns) >= 6:
            tr, tg, tb = struct.unpack(">HHH", trns[:6])
            for i in range(width * height):
                r, g, b = pixels[i * 3], pixels[i * 3 + 1], pixels[i * 3 + 2]
                if r == tr and g == tg and b == tb:
                    rgba[i * 4 + 3] = 0
    elif color_type == 3:
        bpp = 1
        pixels = _unfilter(raw, width, height, bpp)
        if not palette:
            raise ValueError("palette PNG missing PLTE")
        alphas = [255] * len(palette)
        if trns:
            for i, a in enumerate(trns):
                if i < len(alphas):
                    alphas[i] = a
        rgba = bytearray(width * height * 4)
        for i, idx in enumerate(pixels):
            r, g, b = palette[idx]
            rgba[i * 4:i * 4 + 4] = bytes((r, g, b, alphas[idx] if idx < len(alphas) else 255))
    else:
        raise ValueError("color type {0} not supported (need RGB, RGBA or 8-bit palette)".format(color_type))
    return width, height, bytes(rgba)


def _png_chunk(tag, data):
    crc = zlib.crc32(tag + data) & 0xFFFFFFFF
    return struct.pack(">I", len(data)) + tag + data + struct.pack(">I", crc)


def write_png_rgba(path, width, height, rgba):
    raw = bytearray()
    stride = width * 4
    for y in range(height):
        raw.append(0)
        raw.extend(rgba[y * stride:(y + 1) * stride])
    compressed = zlib.compress(bytes(raw), 9)
    ihdr = struct.pack(">IIBBBBB", width, height, 8, 6, 0, 0, 0)
    blob = PNG_SIG + _png_chunk(b"IHDR", ihdr) + _png_chunk(b"IDAT", compressed) + _png_chunk(b"IEND", b"")
    folder = os.path.dirname(path)
    if folder and not os.path.isdir(folder):
        os.makedirs(folder)
    with open(path, "wb") as f:
        f.write(blob)


def _blit_digit(rgba, width, x, y, ch, color, scale=3):
    rows = _DIGITS.get(ch)
    if not rows:
        return
    cr, cg, cb, ca = color
    for ry, row in enumerate(rows):
        for rx, bit in enumerate(row):
            if bit != "1":
                continue
            for oy in range(scale):
                for ox in range(scale):
                    px = x + rx * scale + ox
                    py = y + ry * scale + oy
                    i = (py * width + px) * 4
                    rgba[i:i + 4] = bytes((cr, cg, cb, ca))


def write_test_probe():
    """Flat numbered color frames. Marked test_ — not game art."""
    sprite_id = "test_probe"
    fw = fh = 100
    frames = 4
    colors = [(200, 40, 40, 255), (40, 160, 40, 255), (40, 80, 200, 255), (200, 180, 40, 255)]
    width = fw * frames
    height = fh
    rgba = bytearray(width * height * 4)  # fully transparent
    for fi, col in enumerate(colors):
        ox = fi * fw
        for y in range(2, fh - 2):
            for x in range(2, fw - 2):
                i = (y * width + ox + x) * 4
                rgba[i:i + 4] = bytes(col)
        # black 1px inner outline (visual-guide stand-in, still test_)
        for x in range(2, fw - 2):
            for y in (2, fh - 3):
                i = (y * width + ox + x) * 4
                rgba[i:i + 4] = bytes((0, 0, 0, 255))
        for y in range(2, fh - 2):
            for x in (2, fw - 3):
                i = (y * width + ox + x) * 4
                rgba[i:i + 4] = bytes((0, 0, 0, 255))
        _blit_digit(rgba, width, ox + 40, 38, str(fi), (255, 255, 255, 255), scale=4)

    folder = os.path.join(ART_DIR, sprite_id)
    png_path = os.path.join(folder, "{0}__idle__a0.png".format(sprite_id))
    json_path = os.path.join(folder, "{0}.anim.json".format(sprite_id))
    write_png_rgba(png_path, width, height, rgba)
    spec = {
        "Id": sprite_id,
        "FrameWidth": fw,
        "FrameHeight": fh,
        "Pivot": [50, 98],
        "Angles": 1,
        "Animations": [
            {"Name": "idle", "Fps": 6, "Loop": True, "Frames": frames},
        ],
    }
    if not os.path.isdir(folder):
        os.makedirs(folder)
    with open(json_path, "w", encoding="utf-8") as f:
        json.dump(spec, f, indent=2)
        f.write("\n")
    print("wrote {0}".format(png_path))
    print("wrote {0}".format(json_path))
    return sprite_id


# --- JSON + sheet checks (no unreal) ---

def _file_angles(n_angles):
    if n_angles == 1:
        return [0]
    if n_angles == 5:
        return [0, 1, 2, 3, 4]
    if n_angles == 8:
        return list(range(8))
    return []


def load_spec(folder, sprite_id):
    path = os.path.join(folder, "{0}.anim.json".format(sprite_id))
    rel = "{0}/{0}.anim.json".format(sprite_id)
    errors = []
    if not os.path.isfile(path):
        _log("ERROR", rel, "missing")
        return None, [rel]
    try:
        with open(path, "r", encoding="utf-8") as f:
            data = json.load(f)
    except Exception as exc:
        _log("ERROR", rel, "invalid JSON ({0})".format(exc))
        return None, [rel]

    def need(key, types):
        if key not in data:
            errors.append("{0}: missing {1}".format(rel, key))
            return None
        val = data[key]
        if not isinstance(val, types):
            errors.append("{0}: {1} has wrong type".format(rel, key))
            return None
        return val

    sid = need("Id", (str,))
    fw = need("FrameWidth", (int,))
    fh = need("FrameHeight", (int,))
    pivot = need("Pivot", (list,))
    angles = need("Angles", (int,))
    anims = need("Animations", (list,))
    if sid != sprite_id:
        errors.append("{0}: Id '{1}' != folder '{2}'".format(rel, sid, sprite_id))
    if sid and not NAME_RE.match(sid):
        errors.append("{0}: Id must be english lowercase [a-z][a-z0-9_]*".format(rel))
    if fw is not None and fw <= 0:
        errors.append("{0}: FrameWidth must be > 0".format(rel))
    if fh is not None and fh <= 0:
        errors.append("{0}: FrameHeight must be > 0".format(rel))
    if pivot is not None:
        if len(pivot) != 2 or not all(isinstance(v, int) for v in pivot):
            errors.append("{0}: Pivot must be [x,y] integers".format(rel))
        elif fw and fh and not (0 <= pivot[0] < fw and 0 <= pivot[1] < fh):
            errors.append("{0}: Pivot {1} outside {2}x{3} frame".format(rel, pivot, fw, fh))
    if angles is not None and angles not in ALLOWED_ANGLES:
        errors.append("{0}: Angles must be 1, 5 or 8".format(rel))
    parsed = []
    seen = set()
    if anims is not None:
        if not anims:
            errors.append("{0}: Animations is empty".format(rel))
        for i, anim in enumerate(anims):
            label = "{0} Animations[{1}]".format(rel, i)
            if not isinstance(anim, dict):
                errors.append("{0}: not an object".format(label))
                continue
            name = anim.get("Name")
            fps = anim.get("Fps")
            loop = anim.get("Loop")
            nframes = anim.get("Frames")
            if not isinstance(name, str) or not NAME_RE.match(name):
                errors.append("{0}: Name must be english lowercase [a-z][a-z0-9_]*".format(label))
            elif name in seen:
                errors.append("{0}: duplicate Name '{1}'".format(label, name))
            else:
                seen.add(name)
            if not isinstance(fps, (int, float)) or fps <= 0:
                errors.append("{0}: Fps must be > 0".format(label))
            if not isinstance(loop, bool):
                errors.append("{0}: Loop must be true/false".format(label))
            if not isinstance(nframes, int) or nframes <= 0:
                errors.append("{0}: Frames must be > 0".format(label))
            events = anim.get("Events") or []
            if events and not isinstance(events, list):
                errors.append("{0}: Events must be a list".format(label))
                events = []
            clean_events = []
            for ev in events:
                if not isinstance(ev, dict):
                    errors.append("{0}: event not an object".format(label))
                    continue
                fr = ev.get("Frame")
                evname = ev.get("Name")
                if not isinstance(evname, str) or not evname:
                    errors.append("{0}: event Name missing".format(label))
                if not isinstance(fr, int):
                    errors.append("{0}: event Frame must be int".format(label))
                elif isinstance(nframes, int) and nframes > 0 and not (0 <= fr < nframes):
                    errors.append("{0}: event Frame {1} not in 0..{2}".format(label, fr, nframes - 1))
                else:
                    clean_events.append({"Frame": fr, "Name": evname})
            parsed.append({
                "Name": name,
                "Fps": float(fps) if isinstance(fps, (int, float)) else 6.0,
                "Loop": bool(loop) if isinstance(loop, bool) else True,
                "Frames": nframes if isinstance(nframes, int) else 0,
                "Events": clean_events,
            })

    for msg in errors:
        _log("ERROR", msg)
    if errors:
        return None, errors
    spec = {
        "Id": sid,
        "FrameWidth": fw,
        "FrameHeight": fh,
        "Pivot": [int(pivot[0]), int(pivot[1])],
        "Angles": angles,
        "Animations": parsed,
        "_rel": rel,
        "_folder": folder,
    }
    _log("OK", rel)
    return spec, []


def _pixel(rgba, width, x, y):
    i = (y * width + x) * 4
    return rgba[i], rgba[i + 1], rgba[i + 2], rgba[i + 3]


def check_png(spec, png_path, rel, nframes):
    errors = 0
    try:
        w, h, rgba = read_png(png_path)
    except Exception as exc:
        _log("ERROR", rel, str(exc))
        return 1
    fw, fh = spec["FrameWidth"], spec["FrameHeight"]
    if w != nframes * fw or h != fh:
        _log("ERROR", rel, "size {0}x{1}, expected {2}x{3} (Frames x FrameWidth, FrameHeight)".format(
            w, h, nframes * fw, fh))
        errors += 1
    bad_alpha = 0
    for i in range(0, len(rgba), 4):
        a = rgba[i + 3]
        if a not in (0, 255):
            bad_alpha += 1
            if bad_alpha == 1:
                px = (i // 4) % w if w else 0
                py = (i // 4) // w if w else 0
                _log("ERROR", rel, "alpha {0} at {1},{2} (only 0 or 255)".format(a, px, py))
    if bad_alpha:
        errors += 1
    if w == nframes * fw and h == fh and fw >= 4 and fh >= 4:
        border_fail = 0
        for fi in range(nframes):
            ox = fi * fw
            for y in range(fh):
                for x in range(fw):
                    edge = x < 2 or y < 2 or x >= fw - 2 or y >= fh - 2
                    if not edge:
                        continue
                    _r, _g, _b, a = _pixel(rgba, w, ox + x, y)
                    if a != 0:
                        border_fail += 1
                        if border_fail == 1:
                            _log("ERROR", rel, "frame {0} pixel {1},{2} on 2px margin is not empty".format(
                                fi, x, y))
        if border_fail:
            errors += 1
    if errors == 0:
        _log("OK", rel)
    return errors


def expected_pngs(spec):
    sid = spec["Id"]
    files = []
    for anim in spec["Animations"]:
        for ang in _file_angles(spec["Angles"]):
            name = "{0}__{1}__a{2}.png".format(sid, anim["Name"], ang)
            files.append((name, anim))
    return files


def check_sprite(sprite_id):
    folder = os.path.join(ART_DIR, sprite_id)
    rel_root = sprite_id
    if not os.path.isdir(folder):
        _log("ERROR", rel_root, "missing folder Art/{0}".format(sprite_id))
        return 1
    spec, errs = load_spec(folder, sprite_id)
    if spec is None:
        return 1
    errors = 0
    expected = expected_pngs(spec)
    expected_names = {name for name, _anim in expected}
    present = {n for n in os.listdir(folder) if n.lower().endswith(".png")}
    for name, anim in expected:
        rel = "{0}/{1}".format(sprite_id, name)
        path = os.path.join(folder, name)
        if not os.path.isfile(path):
            _log("ERROR", rel, "missing")
            errors += 1
            continue
        errors += check_png(spec, path, rel, anim["Frames"])
    for extra in sorted(present - expected_names):
        _log("WARN", "{0}/{1}".format(sprite_id, extra), "extra PNG (not in JSON)")
    if errors:
        print("CHECK FAIL {0}".format(sprite_id))
        return 1
    print("CHECK PASS {0}".format(sprite_id))
    return 0


def list_sprite_ids():
    if not os.path.isdir(ART_DIR):
        return []
    ids = []
    for name in sorted(os.listdir(ART_DIR)):
        folder = os.path.join(ART_DIR, name)
        if os.path.isdir(folder) and os.path.isfile(os.path.join(folder, "{0}.anim.json".format(name))):
            ids.append(name)
    return ids


def cmd_check(sprite_id):
    ids = [sprite_id] if sprite_id else list_sprite_ids()
    if not ids:
        _log("ERROR", "Art/", "no sprite folders with .anim.json")
        return 1
    code = 0
    for sid in ids:
        if check_sprite(sid) != 0:
            code = 1
    return code


# --- import (Unreal 5.8 Python API) ---

def _display_angles(n_angles):
    """(angle, source_file_angle, mirrored). Always 0..7 in preview when possible."""
    rows = []
    if n_angles == 8:
        for a in range(8):
            rows.append((a, a, False))
    elif n_angles == 5:
        for a in range(5):
            rows.append((a, a, False))
        for a, src in MIRROR_SRC.items():
            rows.append((a, src, True))
    else:
        rows.append((0, 0, False))
    return rows


def _ue_import(unreal, png_path, dest_path, dest_name):
    tools = unreal.AssetToolsHelpers.get_asset_tools()
    task = unreal.AssetImportTask()
    task.filename = png_path
    task.destination_path = dest_path
    task.destination_name = dest_name
    task.replace_existing = True
    task.replace_existing_settings = True
    task.automated = True
    task.save = True
    tex_factory = unreal.TextureFactory()
    task.factory = tex_factory
    tools.import_asset_tasks([task])
    objs = list(task.get_objects() or [])
    tex = None
    for obj in objs:
        if isinstance(obj, unreal.Texture2D):
            tex = obj
            break
    if tex is None:
        asset_path = dest_path.rstrip("/") + "/" + dest_name
        if unreal.EditorAssetLibrary.does_asset_exist(asset_path):
            tex = unreal.EditorAssetLibrary.load_asset(asset_path)
    if tex is None:
        raise RuntimeError("import produced no Texture2D for {0}".format(png_path))
    tex.set_editor_property("filter", unreal.TextureFilter.TF_NEAREST)
    tex.set_editor_property("mip_gen_settings", unreal.TextureMipGenSettings.TMGS_NO_MIPMAPS)
    tex.set_editor_property("compression_settings", unreal.TextureCompressionSettings.TC_EDITOR_ICON)
    tex.set_editor_property("never_stream", True)
    tex.post_edit_change()
    unreal.EditorAssetLibrary.save_loaded_asset(tex)
    return tex


def _tex_size(tex):
    return int(tex.blueprint_get_size_x()), int(tex.blueprint_get_size_y())


def _create_sprite(unreal, tools, name, package, texture, uv, dim, pivot):
    path = package.rstrip("/") + "/" + name
    if unreal.EditorAssetLibrary.does_asset_exist(path):
        unreal.EditorAssetLibrary.delete_asset(path)
    factory = unreal.PaperSpriteFactory()
    sprite = tools.create_asset(name, package, unreal.PaperSprite, factory)
    if sprite is None:
        raise RuntimeError("PaperSpriteFactory failed for {0}".format(path))
    tw, th = _tex_size(texture)
    sprite.set_editor_property("source_texture", texture)
    sprite.set_editor_property("source_uv", unreal.Vector2D(float(uv[0]), float(uv[1])))
    sprite.set_editor_property("source_dimension", unreal.Vector2D(float(dim[0]), float(dim[1])))
    sprite.set_editor_property("source_texture_dimension", unreal.Vector2D(float(tw), float(th)))
    sprite.set_editor_property("pivot_mode", unreal.SpritePivotMode.CUSTOM)
    sprite.set_editor_property("custom_pivot_point", unreal.Vector2D(float(pivot[0]), float(pivot[1])))
    sprite.set_editor_property("snap_pivot_to_pixel_grid", True)
    sprite.set_editor_property("pixels_per_unreal_unit", 1.0)
    sprite.post_edit_change()
    unreal.EditorAssetLibrary.save_loaded_asset(sprite)
    return sprite


def _create_flipbook(unreal, tools, name, package, sprites, fps):
    path = package.rstrip("/") + "/" + name
    if unreal.EditorAssetLibrary.does_asset_exist(path):
        unreal.EditorAssetLibrary.delete_asset(path)
    factory = unreal.PaperFlipbookFactory()
    flip = tools.create_asset(name, package, unreal.PaperFlipbook, factory)
    if flip is None:
        raise RuntimeError("PaperFlipbookFactory failed for {0}".format(path))
    keys = []
    for spr in sprites:
        kf = unreal.PaperFlipbookKeyFrame()
        kf.set_editor_property("sprite", spr)
        kf.set_editor_property("frame_run", 1)
        keys.append(kf)
    flip.set_editor_property("key_frames", keys)
    flip.set_editor_property("frames_per_second", float(fps))
    flip.post_edit_change()
    unreal.EditorAssetLibrary.save_loaded_asset(flip)
    return flip


def _ensure_preview_map(unreal):
    level_ed = unreal.get_editor_subsystem(unreal.LevelEditorSubsystem)
    if unreal.EditorAssetLibrary.does_asset_exist(PREVIEW_MAP):
        if not level_ed.load_level(PREVIEW_MAP):
            raise RuntimeError("could not load {0}".format(PREVIEW_MAP))
    else:
        parent = "/Game/Lab"
        if not unreal.EditorAssetLibrary.does_directory_exist(parent):
            unreal.EditorAssetLibrary.make_directory(parent)
        if not level_ed.new_level(PREVIEW_MAP, False):
            raise RuntimeError("could not create {0}".format(PREVIEW_MAP))
    return level_ed


def _destroy_tagged(unreal, actor_sub, tag):
    want = str(tag)
    for actor in list(actor_sub.get_all_level_actors()):
        tags = [str(t) for t in (actor.get_editor_property("tags") or [])]
        if want in tags:
            actor_sub.destroy_actor(actor)


def _tag(unreal, actor, *tags):
    actor.set_editor_property("tags", [unreal.Name(t) for t in tags])


def _spawn_preview(unreal, level_ed, spec, flipbooks):
    """flipbooks: {(anim_name, source_angle): (flipbook, loop)}"""
    actor_sub = unreal.get_editor_subsystem(unreal.EditorActorSubsystem)
    sid = spec["Id"]
    fw, fh = spec["FrameWidth"], spec["FrameHeight"]
    _destroy_tagged(unreal, actor_sub, TAG_PREFIX + sid)

    anims = spec["Animations"]
    slots = _display_angles(spec["Angles"])
    gap_y = fw + 40
    gap_z = fh + 80
    spawned = []
    for ai, anim in enumerate(anims):
        for angle, src, mirrored in slots:
            key = (anim["Name"], src)
            if key not in flipbooks:
                continue
            flip, loop = flipbooks[key]
            y = angle * gap_y
            z = -ai * gap_z
            loc = unreal.Vector(0.0, float(y), float(z))
            actor = actor_sub.spawn_actor_from_class(unreal.PaperFlipbookActor, loc, unreal.Rotator(0, 0, 0))
            _tag(unreal, actor, TAG_TOOL, TAG_PREFIX + sid)
            if mirrored:
                actor.set_actor_scale3d(unreal.Vector(-1.0, 1.0, 1.0))
            comp = actor.get_editor_property("render_component")
            comp.set_flipbook(flip)
            comp.set_looping(bool(loop))
            spawned.append(loc)

            label_loc = unreal.Vector(0.0, float(y), float(z + fh * 0.5 + 24))
            text_actor = actor_sub.spawn_actor_from_class(unreal.TextRenderActor, label_loc, unreal.Rotator(0, 180, 0))
            _tag(unreal, text_actor, TAG_TOOL, TAG_PREFIX + sid)
            tr = text_actor.get_editor_property("text_render")
            tr.set_text("{0} a{1}".format(anim["Name"], angle))
            tr.set_world_size(18.0)

    _destroy_tagged(unreal, actor_sub, TAG_RIG)
    if spawned:
        ys = [p.y for p in spawned]
        zs = [p.z for p in spawned]
        mid_y = (min(ys) + max(ys)) * 0.5
        mid_z = (min(zs) + max(zs)) * 0.5
        span_y = max(ys) - min(ys) + fw
        span_z = max(zs) - min(zs) + fh
        dist = max(400.0, span_y, span_z) + 200.0
        cam_loc = unreal.Vector(dist, mid_y, mid_z)
        cam_rot = unreal.Rotator(0.0, 180.0, 0.0)
        cam = actor_sub.spawn_actor_from_class(unreal.CameraActor, cam_loc, cam_rot)
        _tag(unreal, cam, TAG_TOOL, TAG_RIG)
        light_rot = unreal.Rotator(-50.0, -30.0, 0.0)
        light = actor_sub.spawn_actor_from_class(unreal.DirectionalLight, unreal.Vector(0.0, mid_y, mid_z + 200.0), light_rot)
        _tag(unreal, light, TAG_TOOL, TAG_RIG)
        key = level_ed.get_active_viewport_config_key()
        level_ed.set_level_viewport_camera_info(cam_loc, cam_rot, key)
    level_ed.save_current_level()


def import_sprite(unreal, sprite_id):
    if check_sprite(sprite_id) != 0:
        print("IMPORT SKIP {0} (check failed)".format(sprite_id))
        return 1
    folder = os.path.join(ART_DIR, sprite_id)
    spec, _errs = load_spec(folder, sprite_id)
    root = CONTENT_ROOT + "/" + sprite_id
    tex_dir = root + "/Textures"
    spr_dir = root + "/Sprites"
    fb_dir = root + "/Flipbooks"
    if unreal.EditorAssetLibrary.does_directory_exist(root):
        unreal.EditorAssetLibrary.delete_directory(root)
    for d in (root, tex_dir, spr_dir, fb_dir):
        unreal.EditorAssetLibrary.make_directory(d)

    tools = unreal.AssetToolsHelpers.get_asset_tools()
    pivot = spec["Pivot"]
    fw, fh = spec["FrameWidth"], spec["FrameHeight"]
    flipbooks = {}
    for anim in spec["Animations"]:
        for ang in _file_angles(spec["Angles"]):
            png_name = "{0}__{1}__a{2}.png".format(spec["Id"], anim["Name"], ang)
            png_path = os.path.join(folder, png_name)
            tex_name = "T_{0}_{1}_a{2}".format(spec["Id"], anim["Name"], ang)
            tex = _ue_import(unreal, png_path, tex_dir, tex_name)
            sprites = []
            for fi in range(anim["Frames"]):
                spr_name = "S_{0}_{1}_a{2}_{3:02d}".format(spec["Id"], anim["Name"], ang, fi)
                uv = (fi * fw, 0)
                sprites.append(_create_sprite(unreal, tools, spr_name, spr_dir, tex, uv, (fw, fh), pivot))
            fb_name = "FB_{0}_{1}_a{2}".format(spec["Id"], anim["Name"], ang)
            flip = _create_flipbook(unreal, tools, fb_name, fb_dir, sprites, anim["Fps"])
            flipbooks[(anim["Name"], ang)] = (flip, anim["Loop"])
            print("IMPORT {0} {1} a{2} ({3} frames @ {4} fps)".format(
                spec["Id"], anim["Name"], ang, anim["Frames"], anim["Fps"]))

    level_ed = _ensure_preview_map(unreal)
    _spawn_preview(unreal, level_ed, spec, flipbooks)
    print("IMPORT DONE {0} -> {1} and {2}".format(sprite_id, root, PREVIEW_MAP))
    return 0


def cmd_import(sprite_id):
    unreal = _try_unreal()
    if unreal is None:
        print("ERROR import requires Unreal Editor Python (Output Log: py ... import)")
        return 1
    ids = [sprite_id] if sprite_id else list_sprite_ids()
    if not ids:
        _log("ERROR", "Art/", "no sprite folders with .anim.json")
        return 1
    code = 0
    for sid in ids:
        if import_sprite(unreal, sid) != 0:
            code = 1
    return code


def main(argv):
    args = list(argv[1:])
    if not args or args[0] in ("-h", "--help", "help"):
        print("usage: spritelab.py check|import|gen-test [sprite_id]")
        print("check/import without sprite_id processes every Art/<id>/*.anim.json")
        return 0
    cmd = args[0]
    sprite_id = args[1] if len(args) > 1 else None
    if sprite_id and not NAME_RE.match(sprite_id):
        _log("ERROR", sprite_id, "id must be english lowercase [a-z][a-z0-9_]*")
        return 1
    if cmd == "check":
        return cmd_check(sprite_id)
    if cmd == "import":
        return cmd_import(sprite_id)
    if cmd == "gen-test":
        write_test_probe()
        return 0
    print("unknown command {0}".format(cmd))
    return 1


if __name__ == "__main__":
    sys.exit(main(sys.argv))
